try {
  var input = $input.first().json;
  var msg = (input.body && input.body.message) ? input.body.message : input;

  // Phone
  var phone = '';
  if (msg.call && msg.call.customer) {
    phone = msg.call.customer.number || msg.call.customer.phoneNumber || '';
  }
  phone = phone.replace(/\s/g, '');
  if (phone && phone.charAt(0) !== '+') { phone = '+' + phone; }

  // Call metadata
  var callId = (msg.call && msg.call.id) || '';
  var duration = (msg.call && msg.call.duration) ? Math.round(Number(msg.call.duration)) : 0;
  if (!duration && msg.durationSeconds) { duration = Math.round(Number(msg.durationSeconds)); }
  var transcriptUrl = (msg.artifact && msg.artifact.recordingUrl) || (msg.artifact && msg.artifact.stereoRecordingUrl) || '';

  // Structured data (VAPI structuredDataSchema fills this)
  var sd = (msg.analysis && msg.analysis.structuredData) ? msg.analysis.structuredData : {};
  var outcome = sd.outcome || '';
  var callerName = sd.callerName || (msg.call && msg.call.customer && msg.call.customer.name) || '';
  var callerEmail = sd.callerEmail || '';
  var serviceInterest = sd.serviceInterest || '';

  // Outcome fallback logic
  if (!outcome) {
    if (sd.appointmentBooked === true || sd.appointmentBooked === 'true') { outcome = 'booked'; }
    else if (sd.optedOut === true || sd.optedOut === 'true') { outcome = 'do-not-contact'; }
    else if (sd.callbackRequested === true || sd.callbackRequested === 'true') { outcome = 'callback-requested'; }
    else { outcome = 'called'; }
  }

  return [{
    json: {
      phone: phone,
      callId: callId,
      duration: duration,
      transcriptUrl: transcriptUrl,
      outcome: outcome,
      callerName: callerName,
      callerEmail: callerEmail,
      serviceInterest: serviceInterest,
      callDirection: 'inbound'
    }
  }];
} catch(e) {
  return [{
    json: {
      phone: '',
      callId: '',
      duration: 0,
      transcriptUrl: '',
      outcome: 'called',
      callerName: '',
      callerEmail: '',
      serviceInterest: '',
      callDirection: 'inbound',
      parseError: e.message
    }
  }];
}

try {
  var parsed = $('Parse Call Data').first().json;
  var clientRow = $('Read Client Record').first().json;
  var apptRow = $('Read Appointment Record').first().json;
  var msgRows = $('Read Messages').all();
  var config = $('⚙️ Client Config').first().json;

  var isExistingLead = clientRow && clientRow['Phone'] && clientRow['Phone'] !== '';
  var now = new Date().toISOString();

  var existingCount = isExistingLead ? (parseInt(clientRow['Call Count']) || 0) : 0;
  var newCallCount = existingCount + 1;

  var name = parsed.callerName || (isExistingLead ? clientRow['Name'] : '') || '';
  var email = parsed.callerEmail || (isExistingLead ? clientRow['Email'] : '') || '';
  var serviceInterest = parsed.serviceInterest || (isExistingLead ? clientRow['Service Interest'] : '') || '';
  var newStatus = parsed.outcome;
  var leadSource = isExistingLead ? (clientRow['Lead Source'] || 'inbound-call') : 'inbound-call';

  var upcomingAppt = isExistingLead ? (clientRow['Upcoming Appointment'] || '') : '';
  if (parsed.outcome === 'booked') {
    var apptDate = (apptRow && apptRow['Date']) ? apptRow['Date'] : '';
    var apptTime = (apptRow && apptRow['Time']) ? apptRow['Time'] : '';
    if (apptDate && apptTime) { upcomingAppt = apptDate + ' at ' + apptTime; }
  } else if (parsed.outcome === 'not-interested' || parsed.outcome === 'do-not-contact') {
    upcomingAppt = '';
  }

  var smsOptOut = (parsed.outcome === 'do-not-contact') ? 'Y'
                 : (isExistingLead ? (clientRow['SMS Opt-Out'] || 'N') : 'N');

  var smsText = '';
  var smsQueued = 'N';
  var businessName = config.businessName || 'Solarify';
  var displayName = name || 'there';

  function formatCallbackTime(isoStr) {
    try {
      var d = new Date(isoStr);
      if (isNaN(d.getTime())) { return isoStr; }
      var month = d.getUTCMonth() + 1;
      var tzOffset = (month >= 3 && month <= 10) ? 1 : 0;
      var localMs = d.getTime() + tzOffset * 3600000;
      var local = new Date(localMs);
      var day = String(local.getUTCDate()).padStart(2, '0');
      var mon = String(local.getUTCMonth() + 1).padStart(2, '0');
      var hours = String(local.getUTCHours()).padStart(2, '0');
      var mins = String(local.getUTCMinutes()).padStart(2, '0');
      return day + '/' + mon + ' at ' + hours + ':' + mins;
    } catch(fe) { return isoStr; }
  }

  if (smsOptOut !== 'Y') {
    if (parsed.outcome === 'booked') {
      var d = (apptRow && apptRow['Date']) ? apptRow['Date'] : 'your scheduled date';
      var t = (apptRow && apptRow['Time']) ? (' at ' + apptRow['Time']) : '';
      var addr = (apptRow && apptRow['Address']) ? (' Our team will visit you at ' + apptRow['Address'] + '.') : '';
      var svc = (apptRow && apptRow['Service']) ? apptRow['Service'] : (serviceInterest || 'your enquiry');
      smsText = 'Hi ' + displayName + ', your ' + svc + ' appointment is confirmed for ' + d + t + '.' + addr + ' Reply CANCEL to cancel. - ' + businessName;
      smsQueued = 'Y';
    } else if (parsed.outcome === 'callback-requested') {
      smsText = 'Hi ' + displayName + ', we have noted your callback request. We will be in touch shortly. Reply STOP to opt out. - ' + businessName;
      smsQueued = 'Y';
    } else if (parsed.outcome === 'callback-scheduled') {
      var rawCbTime = isExistingLead ? (clientRow['Callback Time'] || '') : '';
      var cbTime = rawCbTime ? formatCallbackTime(rawCbTime) : '';
      smsText = 'Hi ' + displayName + ', your callback is confirmed' + (cbTime ? ' for ' + cbTime : '') + '. We will call you then. Reply STOP to opt out. - ' + businessName;
      smsQueued = 'Y';
    }
  }

  var hasUrgentMessage = false;
  var urgentMsgText = '';
  if (msgRows && msgRows.length > 0) {
    for (var i = 0; i < msgRows.length; i++) {
      var msgRow = msgRows[i].json || {};
      if (msgRow['Urgency'] === 'urgent' && msgRow['Status'] === 'new') {
        hasUrgentMessage = true;
        urgentMsgText = msgRow['Message'] || 'Urgent message received';
        break;
      }
    }
  }
  var urgentAlertText = hasUrgentMessage
    ? 'URGENT INBOUND: ' + (name || parsed.phone) + ' (' + parsed.phone + ') left an urgent message: "' + urgentMsgText + '"'
    : '';

  var callDirection = 'inbound';

  var twilioFrom = config.twilioFromNumber || '';
  var ownerPhone = config.businessOwnerPhone || '';
  var configReady = (twilioFrom.indexOf('PLACEHOLDER') === -1 && ownerPhone.indexOf('PLACEHOLDER') === -1) ? 'Y' : 'N';

  return [{
    json: {
      phone: parsed.phone,
      name: name,
      email: email,
      serviceInterest: serviceInterest,
      leadSource: leadSource,
      callDirection: callDirection,
      status: newStatus,
      outcome: parsed.outcome,
      callCount: newCallCount,
      lastContact: now,
      lastOutcome: parsed.outcome,
      upcomingAppointment: upcomingAppt,
      transcriptUrl: parsed.transcriptUrl,
      createdAt: isExistingLead ? (clientRow['Created At'] || now) : now,
      smsOptOut: smsOptOut,
      smsText: smsText,
      smsQueued: smsQueued,
      hasUrgentMessage: hasUrgentMessage,
      urgentAlertText: urgentAlertText,
      callId: parsed.callId,
      duration: parsed.duration,
      processedAt: now,
      configReady: configReady,
      errorNotes: parsed.parseError || ''
    }
  }];
} catch(e) {
  var fallbackPhone = '';
  try { fallbackPhone = $('Parse Call Data').first().json.phone || ''; } catch(x) {}
  var fallbackCallId = '';
  try { fallbackCallId = $('Parse Call Data').first().json.callId || ''; } catch(x) {}
  var fallbackDuration = 0;
  try { fallbackDuration = $('Parse Call Data').first().json.duration || 0; } catch(x) {}
  var fallbackNow = new Date().toISOString();
  return [{
    json: {
      phone: fallbackPhone,
      outcome: 'called',
      lastOutcome: 'called',
      status: 'called',
      callDirection: 'inbound',
      lastContact: fallbackNow,
      processedAt: fallbackNow,
      callId: fallbackCallId,
      duration: fallbackDuration,
      urgentAlertText: '',
      smsQueued: 'N',
      hasUrgentMessage: false,
      configReady: 'N',
      errorNotes: 'Build payload error: ' + e.message
    }
  }];
}

